    answer: 1,
    hint: 'ב-R יש כמה סוגי חילוק: `/`, `%/%` ו-`%%`. נסו להיזכר מה כל אחד מהם מחזיר, ובמיוחד מה `%%` עושה עם מה שלא מתחלק בדיוק.',
