    whyWrong: {
      0: '`20` היה יוצא אם `fruit` היה המספר `10`: זה מה ש-`(apples + pears) * 2` מדפיס, בלי `paste()`. אבל `paste()` מחזיר טקסט, ולכן `fruit` הוא `"10"`, ועל טקסט אי אפשר לעשות חשבון, גם אם הוא נראה כמו מספר.',
      1: 'חשבון ב-R לא מחזיר טקסט עם מרכאות, ו-R גם לא ממיר טקסט למספר בעצמו. `fruit` הוא `"10"`, ולכן `fruit * 2` עוצר עם שגיאה. (`as.numeric(fruit) * 2` היה מדפיס `20`, בלי מרכאות.)',
      2: 'הסימן `*` לא משכפל טקסט: `"10 10"` הוא מה ש-`paste(fruit, fruit)` מדפיס. `*` מנסה לעשות חשבון, ועל טקסט זה נגמר בשגיאה.'
    }
