      1: '`14` יוצא אם קוראים את `c(3, 1, 2)` כאילו הוא אומר לאן כל עמודה זזה (עמודה 1 למקום 3, עמודה 2 למקום 1...). אבל הווקטור אומר **איזו עמודה** תופיע בכל מקום: במקום הראשון עמודה 3. (`14` היה נכון אילו היה כתוב `c(2, 3, 1)`: אז העמודה הראשונה הייתה `age`.)',
