    code: 'staff <- data.frame(worker = c("Avi", "Bat", "Gil"), dept = c("A", "B", "A"))\npay <- data.frame(worker = c("Avi", "Bat", "Gil"), salary = c(9, 12, 10))\nteam <- merge(staff, pay, by = "worker")\ndim(team)',
