      2: 'כאן חשבתם ש-`merge()` שם את הטבלה השנייה **מתחת** לראשונה, כמו `rbind()`. אבל `merge()` מחבר את הטבלאות זו לצד זו: כל עובד נשאר בשורה אחת, ונוספות לו עמודות.',
      3: 'כאן חשבתם שהעמודה שב-`by` נעלמת אחרי החיבור. היא לא נעלמת: היא נשארת בטבלה, פעם אחת, כדי שיהיה ברור של מי כל שורה.'
