      1: 'זה מה ש-`apply(rain, 1, sum)` מדפיס: ב-`sum()` כל `NA` הופך את התוצאה ל-`NA`. אבל `length()` לא מחשב עם הערכים, הוא רק סופר אותם, ולכן `NA` לא מפריע לו.',
      3: 'זה האורך של כל **עמודה** (3 ערים בכל חודש), ו-`apply(rain, 2, length)` מחשב אותו. `1` פירושו שורות, ולכן יש 3 תוצאות, אחת לכל עיר.'
