      1: '`435` הוא `sum(prices)`, סכום המחירים בלי שום הנחה. הוא יוצא אם חושבים ש-`ifelse()` בודק רק את המחיר הראשון (`40 > 100` הוא `FALSE`) ובוחר לפיו תשובה אחת לכל הווקטור. אבל `ifelse()` בודק כל מיקום בנפרד, ולכן `120` ו-`200` מקבלים הנחה.',
