      2: '`45` יוצא אם רק הבלוק של `else if` רץ. אבל R בודק את התנאים לפי הסדר ומריץ את הראשון שנכון: `40 < 50` כבר `TRUE`, ולכן רץ הבלוק הראשון. (וגם `45 >= 60` הוא `FALSE`, כך ש-`45` לא היה מוכפל.)'
