      2: '`2` הוא מה ש-`best` מדפיס לבד. כאן `best` רק נבדק בתנאי, ומה שמודפס הוא מה שבתוך הבלוק שרץ.',
      3: 'נכון ש-`which()` יכול להחזיר כמה מיקומים, אבל כאן יש רק `TRUE` אחד. לכן `best` הוא מספר אחד, ו-`if` מקבל ערך אחד בלי בעיה.'
