      2: '`"sushi"` יוצא אם בודקים רק את התנאי החיצוני. אבל ההשמה `meal <- "sushi"` נמצאת בתוך `if` פנימי, ו-`30 >= 40` הוא `FALSE`.',
      3: '`else` הוא לא חובה, גם ב-`if` פנימי. כשהתנאי שלו `FALSE` ואין `else`, R פשוט לא מריץ כלום וממשיך הלאה.'
