      2: 'כאן התשובות התחלפו. התשובה השנייה בסוגריים, `"missing"`, היא התשובה ל-`TRUE`, ו-`is.na()` נותן `TRUE` רק במקום של ה-`NA`. (הפלט הזה היה מתקבל עם `!is.na(times)` בתנאי.)'
